// Builds a rotated truck marker icon for the live-tracking truck marker on TrackShipment's
// map — a plain <Marker icon="..."/> URL can't rotate a PNG, but wrapping it in an inline SVG
// <image> with a rotate() transform can. Ported from
// gadidosti-broker-driver/src/lib/truckIcon.js, which established this exact pattern for the
// same problem there.
//
// The PNG is embedded directly as a base64 data: URI inside the SVG (not referenced by a file
// path, even an absolute one) — Google Maps loads marker icons through its own internal image
// pipeline, which silently fails to resolve an <image href="..."> pointing at an external URL
// from inside an already-data-URI SVG, regardless of whether that path is relative or absolute.
// Embedding the bytes directly is the only reliable fix (same root cause + fix as the
// broker-driver version).
//
// headingDeg should already be resolved by the caller (see useStableHeadings in MapView.jsx) —
// this function itself has no memory of the last-known heading, it just draws whatever angle
// it's given, defaulting to 0 (pointing up/north) only when nothing has ever been known.

const TRUCK_PNG_BASE64 = {
  small: "",
  medium: "",
  large: "",
  part: "",
};

// All 4 category PNGs are 3/4-perspective renders (cab/front toward the lower-right of the
// frame, cargo bed/rear toward the upper-left) — not top-down icons drawn facing up/north like
// the rotation math below assumes. Left unrotated, headingDeg=0 would show the truck facing
// roughly southeast instead of north. This offset is a by-eye estimate of that default facing
// direction (degrees clockwise from north/up); subtracting it before rotating brings
// headingDeg=0 back to actually facing north. Re-measure/adjust this by eye against the real
// artwork if the rotation looks off on the map — it isn't derived from pixel measurement.
const ART_FORWARD_OFFSET_DEG = 135;

export const buildTruckIcon = (category, headingDeg) => {
  const base64 = TRUCK_PNG_BASE64[category] || TRUCK_PNG_BASE64.medium;
  const numericHeading = Number(headingDeg);
  const heading = Number.isFinite(numericHeading) ? numericHeading : 0;
  const angle = ((heading - ART_FORWARD_OFFSET_DEG) % 360 + 360) % 360;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40">` +
    `<g transform="rotate(${angle} 20 20)"><image href="data:image/png;base64,${base64}" x="4" y="4" width="32" height="32" /></g>` +
    `</svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};
